    row_dividers = [
        r for r in range(h)
        if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])
    ]
    col_dividers = [
        c for c in range(w)
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))
    ]

    def segments(length, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < length:
            result.append((start, length))
        return result

    row_segments = segments(h, row_dividers)
    col_segments = segments(w, col_dividers)
    out = [row[:] for row in grid]

    def contains_color(ri, ci, color):
        r0, r1 = row_segments[ri]
        c0, c1 = col_segments[ci]
        return any(grid[r][c] == color
                   for r in range(r0, r1) for c in range(c0, c1))

    # Each matching mirrored pair establishes a color-specific relation
    # between two neighboring panels.
    relations = set()
    for ri, (r0, r1) in enumerate(row_segments):
        for ci in range(len(col_segments) - 1):
            a0, a1 = col_segments[ci]
            b0, b1 = col_segments[ci + 1]
            if a1 - a0 != b1 - b0:
                continue
            colors = {
                grid[r][c]
                for r in range(r0, r1)
                for c in range(a0, a1)
                if grid[r][c] != 0
            }
            for color in colors:
                if not contains_color(ri, ci + 1, color):
                    continue
                width = a1 - a0
                if all(
                    (grid[r][a0 + k] == color)
                    == (grid[r][b1 - 1 - k] == color)
                    for r in range(r0, r1)
                    for k in range(width)
                ):
                    relations.add((ci, ci + 1, color))

    for left, right, color in relations:
        for ri, (r0, r1) in enumerate(row_segments):
            left_has = contains_color(ri, left, color)
            right_has = contains_color(ri, right, color)
            if left_has == right_has:
                continue

            src, dst = (left, right) if left_has else (right, left)
            s0, s1 = col_segments[src]
            d0, _ = col_segments[dst]
            width = s1 - s0

            for r in range(r0, r1):
                for k in range(width):
                    if grid[r][s1 - 1 - k] == color:
                        out[r][d0 + k] = color

    return out
